"""Symmetry operations for the 230 space groups.

The operations were generated with spglib 2.8.0 (BSD-3 license) from its
space-group database, using the standard setting of each group; rhombohedral
groups use hexagonal axes so that they match the hexagonal lattice matrix
returned by Space_Group_L.

Reference: A. Togo, K. Shinohara and I. Tanaka, Spglib: a software library
for crystal symmetry search, Sci. Technol. Adv. Mater. Methods 4, 2384822
(2024), doi:10.1080/27660400.2024.2384822.

Each operation is an affine map in fractional coordinates, x' = R @ x + t,
with R a 3x3 integer rotation or reflection matrix and t a fractional
translation. The expansion into molecular orientations is done in
Space_Group_Expand.
"""

from __future__ import annotations

from fractions import Fraction

import numpy as np


class SymmetryOperator:
    """A crystallographic symmetry operation as an affine map."""

    def __init__(self, rotation, translation):
        self.rotation = np.asarray(rotation, dtype=int)
        self.translation = tuple(Fraction(s) for s in translation)
        self._translation_float = np.array([float(v) for v in self.translation])

    def apply_to_fractional(self, xyz, wrap=True):
        """
        Inputs: fractional coordinates; whether to wrap the result into [0, 1).

        Returns: the transformed fractional coordinates.
        """
        v = self.rotation @ np.asarray(xyz, dtype=float) + self._translation_float
        if wrap:
            v = v % 1.0
        return v

    def cartesian_rotation(self, lattice_matrix):
        """
        Inputs: 3x3 lattice matrix whose columns are the vectors a, b, c.

        Returns: the rotation matrix in Cartesian coordinates.
        """
        L = np.asarray(lattice_matrix, dtype=float)
        return L @ self.rotation.astype(float) @ np.linalg.inv(L)

    def apply_to_cartesian_vector(self, vector, lattice_matrix):
        """
        Inputs: Cartesian vector; 3x3 lattice matrix.

        Returns: the vector after the operation, in Cartesian coordinates.
        """
        R = self.cartesian_rotation(lattice_matrix)
        return R @ np.asarray(vector, dtype=float)

    def apply_to_cartesian_tensor(self, tensor, lattice_matrix):
        """
        Inputs: second-order Cartesian tensor; 3x3 lattice matrix.

        Returns: the rotated tensor R @ T @ R.T.
        """
        R = self.cartesian_rotation(lattice_matrix)
        T = np.asarray(tensor, dtype=float)
        return R @ T @ R.T

    def __repr__(self):
        return f"SymmetryOperator(R={self.rotation.tolist()!r}, t={self.translation!r})"


class SpaceGroup:
    """All symmetry operations of one space group."""

    def __init__(self, number, symbol, crystal_system, lattice_type, operations):
        self.number = int(number)
        self.symbol = str(symbol)
        self.crystal_system = str(crystal_system)
        self.lattice_type = str(lattice_type)
        self.operations = tuple(operations)
        self.order = len(self.operations)

    @classmethod
    def from_data(cls, data):
        """
        Inputs: one entry of SPACE_GROUP_DATA.

        Returns: the corresponding SpaceGroup object.
        """
        operations = [
            SymmetryOperator(item["rotation"], item["translation"])
            for item in data["operations"]
        ]
        return cls(
            number=data["number"],
            symbol=data["symbol"],
            crystal_system=data["crystal_system"],
            lattice_type=data["lattice_type"],
            operations=operations,
        )

    def equivalent_fractional_positions(self, xyz, tol=1e-8, wrap=True):
        """
        Inputs: initial fractional coordinates; deduplication tolerance;
        whether to wrap positions into [0, 1).

        Returns: the unique symmetry-equivalent fractional positions.
        """
        positions = []
        for op in self.operations:
            p = op.apply_to_fractional(xyz, wrap=wrap)
            if not any(np.linalg.norm(p - q) < tol for q in positions):
                positions.append(p)
        return positions

    def equivalent_cartesian_positions(self, xyz_fractional, lattice_matrix, tol=1e-8, wrap=True):
        """
        Inputs: initial fractional coordinates; 3x3 lattice matrix;
        deduplication tolerance; whether to wrap positions into [0, 1).

        Returns: the unique equivalent positions in Cartesian coordinates.
        """
        L = np.asarray(lattice_matrix, dtype=float)
        frac = self.equivalent_fractional_positions(xyz_fractional, tol=tol, wrap=wrap)
        return [L @ p for p in frac]

    def cartesian_rotations(self, lattice_matrix):
        """
        Inputs: 3x3 lattice matrix.

        Returns: the Cartesian rotation matrix of every operation.
        """
        return [op.cartesian_rotation(lattice_matrix) for op in self.operations]

    def __repr__(self):
        return f"SpaceGroup(number={self.number}, symbol={self.symbol!r}, order={self.order})"


CRYSTAL_SYSTEM_RANGES = {
    (1, 2): "triclinic",
    (3, 15): "monoclinic",
    (16, 74): "orthorhombic",
    (75, 142): "tetragonal",
    (143, 167): "trigonal",
    (168, 194): "hexagonal",
    (195, 230): "cubic",
}

def crystal_system_for(number):
    """
    Inputs: space group number.

    Returns: the crystal system name.
    """
    number = int(number)
    for (lo, hi), name in CRYSTAL_SYSTEM_RANGES.items():
        if lo <= number <= hi:
            return name
    raise ValueError(f"invalid space group number: {number}")


