def get_space_group(number):
    """
    Inputs: space group number (1-230).

    Returns: the corresponding SpaceGroup object.
    """
    number = int(number)
    if number not in SPACE_GROUP_DATA:
        raise ValueError(f"unknown space group number: {number}")
    return SpaceGroup.from_data(SPACE_GROUP_DATA[number])


